/**
 * Simple interactive Box with integrated clickable state management.
 *
 * This composable infers its style from the current [SnyggTheme][org.drs.lib.snygg.SnyggTheme], which is
 * required to be provided by [ProvideSnyggTheme].
 *
 * @param elementName The name of this element. If `null` the style will be inherited from the parent element.
 * @param attributes The attributes of the element used to refine the query.
 * @param modifier The modifier to be applied to the icon button.
 * @param onClick called when this icon button is clicked
 * @param enabled controls the enabled state of this icon button. When `false`, this component will not respond to user
 *    input, and it will appear visually disabled and disabled to accessibility services.
 * @param contentDescription Optional accessibility label announced by TalkBack for this button. It is set as semantics
 *    on the clickable Box, so it merges with the semantics of the child content (an unlabeled decorative child icon
 *    stays silent). Prefer a localized label whenever the button is icon-only.
 * @param interactionSource an optional hoisted [MutableInteractionSource] for observing and emitting [Interaction]s for
 *    this button. You can use this to change the button's appearance or preview the button in different states. Note
 *    that if `null` is provided, interactions will still happen internally.
 * @param content The content displayed on the icon button, expected to be icon.
 */
@Composable
fun SnyggIconButton(
    elementName: String? = null,
    attributes: SnyggQueryAttributes = emptyMap(),
    modifier: Modifier = Modifier,
    onClick: () -> Unit,
    onLongClick: (() -> Unit)? = null,
    enabled: Boolean = true,
    contentDescription: String? = null,
    interactionSource: MutableInteractionSource? = null,
    content: @Composable () -> Unit,
) {
    val interactionSource = interactionSource ?: remember { MutableInteractionSource() }
    val selector = if (enabled) SnyggSelector.NONE else SnyggSelector.DISABLED
    ProvideSnyggStyle(elementName, attributes, selector) { style ->
        // DRS a11y/i18n/ux (r0-F): the clickable Box previously exposed no semantics of its own, so icon-only
        // SnyggIconButtons were invisible to TalkBack (no focus, no label, no click action). The optional
        // [contentDescription] is set as semantics on the clickable Box itself (merging with the child content
        // semantics), and minimumInteractiveComponentSize enforces the 48dp minimum touch target recommended
        // for actionable icons regardless of how small the themed visual box renders.
        Box(
            modifier = Modifier
                .snyggMargin(style)
                .snyggShadow(style)
                .snyggBorder(style)
                .snyggBackground(style, allowClip = true)
                .then(modifier)
                .minimumInteractiveComponentSize()
                .semantics {
                    if (contentDescription != null) {
                        this.contentDescription = contentDescription
                    }
                }
                .combinedClickable(
                    onClick = onClick,
                    onLongClick = onLongClick,
                    enabled = enabled,
                    role = Role.Button,
                    interactionSource = interactionSource,
                    indication = ripple(),
                )
                .snyggPadding(style),
            contentAlignment = Alignment.Center,
        ) {
            val foreground = style.foreground
            if (foreground is SnyggStaticColorValue) {
                CompositionLocalProvider(LocalContentColor provides foreground.color, content = content)
            } else {
                content()
            }
        }
    }
}

@Preview
@Composable
private fun SimpleSnyggIconButton() {
    val stylesheet = SnyggStylesheet.v2 {
        "preview-column" {
            background = rgbaColor(255, 255, 255)
            fontSize = fontSize(20.sp)
            foreground = rgbaColor(0, 0, 255)
            padding = padding(6.dp)
        }
        "preview-icon" {
            background = rgbaColor(180, 180, 180)
            foreground = rgbaColor(0, 0, 0)
            shape = roundedCornerShape(4.dp)
        }
    }
    val theme = rememberSnyggTheme(stylesheet)

    ProvideSnyggTheme(theme) {
        SnyggColumn("preview-column") {
            SnyggText("preview-text", text = "blue text")
            SnyggIconButton(
                "preview-icon",
                onClick = {},
            ) {
                SnyggIcon("preview-icon", imageVector = Icons.Default.Search)
            }
        }
    }
}
